CREATE TRIGGER invoice_lines_locked_insert BEFORE INSERT ON invoice_lines WHEN (SELECT status FROM invoices WHERE id=NEW.invoice_id) NOT IN ('draft') BEGIN SELECT RAISE(ABORT,'approved or posted detail is immutable'); END;
CREATE TRIGGER invoice_lines_locked_update BEFORE UPDATE ON invoice_lines WHEN (SELECT status FROM invoices WHERE id=NEW.invoice_id) NOT IN ('draft') OR (SELECT status FROM invoices WHERE id=OLD.invoice_id) NOT IN ('draft') BEGIN SELECT RAISE(ABORT,'approved or posted detail is immutable'); END;
CREATE TRIGGER invoice_lines_locked_delete BEFORE DELETE ON invoice_lines WHEN (SELECT status FROM invoices WHERE id=OLD.invoice_id) NOT IN ('draft') BEGIN SELECT RAISE(ABORT,'approved or posted detail is immutable'); END;
