CREATE TRIGGER goods_receipt_lines_locked_delete BEFORE DELETE ON goods_receipt_lines WHEN (SELECT status FROM goods_receipts WHERE id=OLD.goods_receipt_id) NOT IN ('draft') BEGIN SELECT RAISE(ABORT,'approved or posted detail is immutable'); END;
